def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    opp_defects = sum(1 for a in opp if a == 'D')

    # Fast, strong retaliation to break sustained defection early,
    # while avoiding permanent lock-in against TFT-style opponents.
    if n < 3:
        return 'C'

    last_opp = opp[-1]

    # Detect sustained defection quickly.
    if n >= 3 and opp[-1] == 'D' and opp[-2] == 'D':
        if n >= 4 and opp[-3] == 'D':
            # Long run of defection: mostly defect, rare probe to re-open.
            if n % 13 == 0:
                return 'C'
            return 'D'
        # Two defections in a row: retaliate once, then be willing to forgive.
        return 'D'

    # Endgame: exploit likely cooperators only very late.
    remaining = 100 - n
    if remaining <= 1:
        if opp_defects == 0:
            return 'D'
        if last_opp == 'D':
            return 'D'
        return 'D'

    # Almost-always-defect opponent.
    if n >= 6 and opp_defects * 5 >= n * 4:
        if n % 9 == 0:
            return 'C'
        return 'D'

    # Mostly cooperative opponent: cooperate, with sparse controlled probes.
    opp_coop = n - opp_defects
    if opp_coop * 4 >= n * 3:
        if last_opp == 'D':
            # Forgive quickly to avoid punishing a mostly-cooperative partner.
            if rng.random() < 0.45:
                return 'C'
            return 'D'
        # Rare probing, but not near the very end if it risks collapse.
        if n >= 12 and remaining > 6:
            if n % 17 == 0 and rng.random() < 0.25:
                return 'D'
        return 'C'

    # Moderate opponent: tit-for-tat with occasional forgiveness and probes.
    if last_opp == 'C':
        if me[-1] == 'D':
            # We defected and they forgave: return to cooperation.
            return 'C'
        if n >= 8 and opp_defects * 2 < n:
            if n % 23 == 0 and remaining > 10 and rng.random() < 0.2:
                return 'D'
        return 'C'

    # Opponent just defected.
    # Retaliate, but if their overall defection rate is low, sometimes forgive.
    if opp_defects * 2 < n:
        if rng.random() < 0.35:
            return 'C'
        return 'D'

    # Defect back, avoid endless mutual defection with occasional olive branch.
    if n % 11 == 0:
        return 'C'
    return 'D'
